new Promise(function(res){var img=new Image();img.onload=function(){try{var c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;var g=c.getContext('2d');g.drawImage(img,0,0);var dA=g.getImageData(800,330,1,60).data;var col=[];for(var i=0;i<60;i++)col.push([330+i,dA[i*4],dA[i*4+1],dA[i*4+2]]);var dB=g.getImageData(1355,188,63,28).data,dark=0;for(var j=0;j<dB.length;j+=4){var R=dB[j],G=dB[j+1],B=dB[j+2];if(R<130&&G<130&&B<130)dark++;}var thumb=[];for(var y=150;y<900;y+=2){var d=g.getImageData(540,y,880,1).data,run=0,mx=0;for(var x=0;x<880;x++){var R=d[x*4],G=d[x*4+1],B=d[x*4+2];if(Math.abs(R-G)<=2&&Math.abs(G-B)<=2&&R>=150&&R<=225){run++;if(run>mx)mx=run;}else run=0;}if(mx>=300)thumb.push(y);}res(JSON.stringify({colX800:col,opsDark:dark,thumbRows:thumb.slice(0,6)}));}catch(e){res('EXC:'+e.message);}};img.onerror=function(){res('IMGERR');};img.src='data:image/png;base64,';})